// ==== CONFIGURE AQUI ====
const QDRANT_URL = 'https://01232c5c-728d-4190-a9ad-5e2cb71dad5d.europe-west3-0.gcp.cloud.qdrant.io';
const COLECAO_MINUTA = 'minuta_ultima_versao';      // alias criado pelo notebook de ingestão
const COLECAO_GLOSSARIO = 'glossario_ultima_versao';
const VERSAO = 'Rev.05 r1';   // troque quando ingerir uma minuta nova: o cache é separado por versão
const USAR_CACHE = true;
const MODELO = 'gpt-6-luna';   // OpenAI
// 'economico': manda à IA só os artigos que a varredura achou (+ seções deles), abaixo de 100 mil tokens,
//   faixa em que o Haiku custa 5x menos. 'completo': manda a minuta inteira (mais caro).
const MODO = 'economico';
const LIMITE_CARACTERES = 240000;   // ~65 mil tokens de artigos no modo econômico
const MAX_TOKENS_RESPOSTA = 16000;   // trocas na minuta toda podem listar dezenas de artigos
// ========================

const corpo = $input.first().json.body || {};
const pergunta = String(corpo.pergunta || '').trim();
if (pergunta.length < 4) throw new Error('Pergunta vazia ou curta demais.');
if (pergunta.length > 2000) throw new Error('Pergunta longa demais (máx. 2000 caracteres).');

const pergunta_norm = pergunta.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase()
  .replace(/[“”«»]/g, '"').replace(/[‘’]/g, "'").replace(/\s+/g, ' ').replace(/\s*([?!.])+\s*$/, '').trim();

return [{ json: {
  versao: VERSAO, usar_cache: USAR_CACHE, pergunta_norm, t0: Date.now(),
  qdrant_url: QDRANT_URL.replace(/\/+$/, ''), colecao_minuta: COLECAO_MINUTA, colecao_glossario: COLECAO_GLOSSARIO,
  modelo: MODELO, max_tokens: MAX_TOKENS_RESPOSTA, pergunta, modo: MODO, limite_caracteres: LIMITE_CARACTERES,
} }];

const cfg = $('Configurar e Validar').first().json;
const c = $input.first().json.cache;
const quando = new Date(c.criado_em).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const saida = Object.assign({}, c.resposta, {
  rota: 'cache', tipo: c.resposta.tipo || null, custo_usd: 0,
  aviso_rota: 'Resposta reaproveitada de uma consulta igual feita em ' + quando + ' (sem custo).',
});
return [{ json: { saida, registro: {
  pergunta: cfg.pergunta, pergunta_norm: cfg.pergunta_norm, versao: cfg.versao, tipo: saida.tipo || 'tema', rota: 'cache',
  resposta: saida, valida: true, custo_usd: 0, duracao_ms: Date.now() - cfg.t0, origem_cache_id: c.id,
} } }];

const cfg = $('Configurar e Validar').first().json;
const pontos = ($('Ler Minuta Completa').first().json.result || {}).points || [];
const glossPts = ($('Ler Glossário').first().json.result || {}).points || [];
if (pontos.length < 50) throw new Error('A coleção da minuta voltou com ' + pontos.length + ' artigos. Confira o alias no Qdrant.');

const arts = pontos.map((p) => p.payload).filter((p) => p && p.numero != null)
  .sort((a, b) => a.numero - b.numero);
const porNum = new Map(arts.map((a) => [Number(a.numero), a]));
const gloss = glossPts.map((p) => p.payload).filter((g) => g && g.termo);

// ---------- normalização (sem acento, minúsculas) ----------
const semAc = (s) => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const L = '[\\p{L}\\p{N}]';
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
function contar(termo, texto) {
  const t = semAc(termo).trim().replace(/\s+/g, ' ');
  if (t.length < 2) return 0;
  const re = new RegExp('(?<!' + L + ')' + esc(t).replace(/ /g, '\\s+') + '(?!' + L + ')', 'gu');
  return (semAc(texto).match(re) || []).length;
}
const textoN = new Map(arts.map((a) => [a.numero, semAc(a.texto_artigo)]));
function varrer(termo) {
  const achados = [];
  for (const a of arts) { const c = contar(termo, a.texto_artigo); if (c) achados.push({ artigo: a.numero, ocorrencias: c }); }
  return achados;
}

const q = cfg.pergunta;
// 1) artigos citados pelo número: "art. 45", "artigo 45", "arts. 10 e 12"
const alvos = new Set();
for (const m of q.matchAll(/\b(?:arts?\.?|artigos?)\s*((?:\d+\s*[º°o]?\s*(?:,|e|a|ou)?\s*)+)/gi)) {
  for (const n of m[1].match(/\d+/g) || []) if (porNum.has(Number(n))) alvos.add(Number(n));
}
// 2) termos entre aspas: "poderá", “deverá”, 'segurança viária', «...»
const termos = new Set();
for (const m of q.matchAll(/["“”'‘’«»]([^"“”'‘’«»]{2,80})["“”'‘’«»]/g)) termos.add(m[1].trim());

// 3) para cada artigo-alvo: quem remete a ele, mesma seção e conceitos que ele usa
const remissoes = [];
const mesmaSecao = [];
const conceitos = new Map();
const MINUSC = new Set(['de', 'da', 'do', 'das', 'dos', 'e', 'para', 'em', 'a', 'o']);
const GENERICOS = new Set(['plano diretor', 'lei federal', 'lei municipal', 'lei complementar', 'poder publico', 'municipio', 'poder executivo', 'curitiba', 'estatuto da cidade', 'constituicao federal']);
for (const n of alvos) {
  const a = porNum.get(n);
  // remissões internas: "art. 45" sem "da Lei/do Decreto..." logo depois
  const reRem = new RegExp('\\b(?:arts?\\.?|artigos?)\\s*(?:\\d+\\s*[º°o]?\\s*(?:,|e|a|ou)\\s*)*' + n + '(?!\\d)(?:\\s*[º°o])?(?![^.;]{0,40}\\b(?:da|do)\\s+(?:Lei|Decreto|Constitui|Estatuto|C[óo]digo))', 'i');
  for (const b of arts) if (b.numero !== n && reRem.test(b.texto_artigo)) remissoes.push({ alvo: n, artigo: b.numero });
  for (const b of arts) if (b.numero !== n && b.breadcrumb && b.breadcrumb === a.breadcrumb) mesmaSecao.push({ alvo: n, artigo: b.numero });
  // conceitos do alvo: termos do glossário presentes nele, siglas e nomes próprios compostos
  const cand = new Set();
  for (const g of gloss) { const base = String(g.termo).replace(/\s*\(.*?\)\s*$/, '').trim(); if (contar(base, a.texto_artigo)) cand.add(base); }
  for (const m of a.texto_artigo.matchAll(/\b[A-ZÁÉÍÓÚÂÊÔÃÕÇ]{3,}s?\b/g)) cand.add(m[0]);
  const palavras = a.texto_artigo.replace(/^Art\.\s*\d+\S*\s*/, '').split(/(\s+|[,;:.()])/);
  let atual = [];
  const fechar = () => {
    while (atual.length && MINUSC.has(atual[atual.length - 1].toLowerCase())) atual.pop();
    const maius = atual.filter((w) => /^[A-ZÁÉÍÓÚÂÊÔÃÕÇ]/.test(w)).length;
    if (maius >= 2) cand.add(atual.join(' '));
    atual = [];
  };
  for (const w of palavras) {
    if (!w.trim()) continue;
    if (/^[A-ZÁÉÍÓÚÂÊÔÃÕÇ][\p{L}-]+$/u.test(w)) atual.push(w);
    else if (atual.length && MINUSC.has(w.toLowerCase())) atual.push(w);
    else fechar();
  }
  fechar();
  for (const c of cand) {
    if (/^(Art|Lei|Inciso|Parágrafo|Este|Esta|Os|As)$/i.test(c)) continue;
    if (GENERICOS.has(semAc(c))) continue;
    const ach = varrer(c).filter((x) => x.artigo !== n);
    // conceito presente em muitos artigos é genérico demais para indicar impacto
    if (ach.length && ach.length <= 25) conceitos.set(c, { conceito: c, alvo: n, artigos: ach });
  }
}

// Pergunta de alteração ("trocar 'poderá' por 'deverá' no art. 63"): os termos entre aspas são a edição,
// não o tema. Eles são contados (para mostrar o uso no resto da minuta), mas não entram no checklist.
// Troca explícita: "trocar/mudar "X" por/para "Y"". X = termo original (onde a troca acontece), Y = termo novo.
const troca = q.match(/(?:troc|mud|substitu|alter|modific)[^"“”']{0,60}["“']([^"“”']{1,60})["”'][^"“”']{0,25}?\b(?:por|para|pelo|pela)\s+["“']([^"“”']{1,60})["”']/i);
const termoOriginal = troca ? troca[1].trim() : null;
const termoNovo = troca ? troca[2].trim() : null;
const ehAlteracao = !!troca || (alvos.size > 0 && /\b(troc|mud|substitu|alter|modific|passa[rn]?\b|reda[çc][ãa]o|emenda)/i.test(q));
const listaTermos = [...termos].map((t) => {
  const ach = varrer(t);
  let papel = 'tema';
  if (termoOriginal && semAc(t) === semAc(termoOriginal)) papel = 'original';
  else if (termoNovo && semAc(t) === semAc(termoNovo)) papel = 'novo';
  else if (ehAlteracao) papel = 'edicao';
  return { termo: t, papel, total: ach.reduce((s, x) => s + x.ocorrencias, 0), artigos: ach, edicao: papel !== 'tema',
           no_alvo: [...alvos].map((n) => ({ artigo: n, ocorrencias: contar(t, porNum.get(n).texto_artigo) })) };
});

// 4) conjunto completo a ser avaliado (checklist)
const motivos = new Map();
const marcar = (n, m) => { if (!motivos.has(n)) motivos.set(n, new Set()); motivos.get(n).add(m); };
for (const n of alvos) marcar(n, 'artigo citado na pergunta');
for (const r of remissoes) marcar(r.artigo, 'remete ao Art. ' + r.alvo);
for (const s of mesmaSecao) marcar(s.artigo, 'mesma seção do Art. ' + s.alvo);
for (const c of conceitos.values()) for (const x of c.artigos) marcar(x.artigo, 'usa "' + c.conceito + '"');
for (const t of listaTermos) {
  if (t.papel === 'tema') for (const x of t.artigos) marcar(x.artigo, 'contém "' + t.termo + '"');
  // troca na minuta toda (sem artigo citado): todo artigo com o termo original muda de redação
  if (t.papel === 'original' && !alvos.size) for (const x of t.artigos) marcar(x.artigo, 'tem "' + t.termo + '" (' + x.ocorrencias + 'x), que seria trocado por "' + termoNovo + '"');
}
const checklist = [...motivos.entries()].sort((a, b) => a[0] - b[0]).map(([n, m]) => ({ artigo: n, motivos: [...m] }));

// ---------- contexto enviado à IA ----------
function bloco(a) { return (a.breadcrumb ? '[' + a.breadcrumb + ']\n' : '') + a.texto_artigo; }
function contexto() {
  if (cfg.modo === 'completo') {
    return { modo: 'completo', artigos_no_contexto: arts.length,
      minuta_texto: arts.map(bloco).join('\n\n'),
      glossario_texto: gloss.map((g) => g.termo + ': ' + g.definicao).join('\n') };
  }
  // econômico: checklist primeiro; depois a seção de cada artigo citado; se nada foi achado,
  // os artigos com mais palavras da pergunta (busca literal, sem IA)
  const escolhidos = [];
  const add = (n) => { if (porNum.has(n) && !escolhidos.includes(n)) escolhidos.push(n); };
  for (const n of alvos) add(n);
  for (const c of checklist) add(c.artigo);
  // artigo citado: inclui o capítulo dele inteiro (contexto para analisar a alteração)
  for (const n of alvos) {
    const cap = String(porNum.get(n).breadcrumb || '').split(' > ').slice(0, 2).join(' > ');
    if (cap) arts.filter((a) => String(a.breadcrumb || '').startsWith(cap)).slice(0, 40).forEach((a) => add(a.numero));
  }
  if (!escolhidos.length) {
    const PARE = new Set(['sobre', 'quais', 'qual', 'minuta', 'artigo', 'artigos', 'plano', 'diretor', 'como', 'onde', 'quando', 'existe', 'falam', 'trata', 'tratam', 'dispoe', 'preve']);
    const palavras = [...new Set(semAc(q).match(/[\p{L}]{5,}/gu) || [])].filter((w) => !PARE.has(w));
    const nota = arts.map((a) => ({ n: a.numero, s: palavras.reduce((t, w) => t + (textoN.get(a.numero).includes(w) ? 1 : 0), 0) }))
      .filter((x) => x.s > 0).sort((a, b) => b.s - a.s || a.n - b.n).slice(0, 40);
    for (const x of nota) add(x.n);
  }
  let tam = 0; const dentro = [];
  for (const n of escolhidos) { const t = bloco(porNum.get(n)); if (tam + t.length > cfg.limite_caracteres) break; tam += t.length; dentro.push(n); }
  const cortados = escolhidos.filter((n) => !dentro.includes(n));
  const textoSel = dentro.sort((a, b) => a - b).map((n) => bloco(porNum.get(n))).join('\n\n');
  const glossSel = gloss.filter((g) => { const base = String(g.termo).replace(/\s*\(.*?\)\s*$/, ''); return contar(base, q) || contar(base, textoSel); });
  return { modo: 'economico', artigos_no_contexto: dentro.length, artigos_fora_por_limite: cortados,
    minuta_texto: textoSel, glossario_texto: glossSel.map((g) => g.termo + ': ' + g.definicao).join('\n') };
}

return [{ json: {
  pergunta: q,
  alvos: [...alvos],
  eh_alteracao: ehAlteracao,
  troca: troca ? { original: termoOriginal, novo: termoNovo, escopo: alvos.size ? 'artigos citados' : 'minuta inteira' } : null,
  termos: listaTermos,
  remissoes, mesma_secao: mesmaSecao,
  conceitos: [...conceitos.values()].map((c) => ({ conceito: c.conceito, alvo: c.alvo, artigos: c.artigos.map((x) => x.artigo) })),
  checklist,
  total_artigos_minuta: arts.length,
  // texto completo, em ordem fixa (a ordem estável é o que permite o cache do prompt)
  ...contexto(),
} }];

const cfg = $('Configurar e Validar').first().json;
const v = $input.first().json;
const pontos = ($('Ler Minuta Completa').first().json.result || {}).points || [];
const gloss = (($('Ler Glossário').first().json.result || {}).points || []).map((p) => p.payload).filter((g) => g && g.termo);
const arts = pontos.map((p) => p.payload).filter((p) => p && p.numero != null).sort((a, b) => a.numero - b.numero);
const porNum = new Map(arts.map((a) => [Number(a.numero), a]));

const semAc = (s) => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const L = '[\\p{L}\\p{N}]';
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const reTermo = (t, prefixo) => new RegExp('(?<!' + L + ')' + esc(semAc(t).trim().replace(/\s+/g, ' ')).replace(/ /g, '\\s+') + (prefixo ? L + '*' : '(?!' + L + ')'), 'gu');
function achar(termo, prefixo) {
  const re = reTermo(termo, prefixo); const out = [];
  for (const a of arts) {
    const n = semAc(a.texto_artigo); const m = n.match(re);
    if (m) {
      re.lastIndex = 0; const i = n.search(re);
      const ini = Math.max(0, i - 70), trecho = a.texto_artigo.slice(ini, i + 110).replace(/\s+/g, ' ').trim();
      out.push({ artigo: a.numero, ocorrencias: m.length, trecho: (ini ? '…' : '') + trecho + '…', titulo: (a.breadcrumb || '').split(' > ')[0] });
    }
  }
  return out;
}
const rot = (n) => n < 10 ? 'Art. ' + n + 'º' : 'Art. ' + n;
const q = cfg.pergunta, qn = cfg.pergunta_norm;
const alvos = v.alvos || [];
const aspas = (v.termos || []).map((t) => t.termo);

const ANALISE = /\b(impacto|impacta|impactos|consequen|efeito|afeta|afetaria|por que|porque|analis|explique|explica|resum|compar|diferen|avali|riscos?|o que muda|mudaria|contradi|conflit)/;
const ALTERA = /\b(troc|mud[ae]|mudar|mudan|substitu|alter|modific|suprim|revog|exclu|retir|acrescent|inclu[ia]r|nova redacao|emenda|reescrev)/;
const LOCALIZA = /\b(quais|qual artigo|quantos|quantas|quantidade|lista|listar|liste|onde|em que artigo|em quais|aparece|aparecem|ocorre|ocorrencia|menciona|mencionam|cita|citam|contem|contém|tem|tem o termo|possuem|possui|falam|fala|tratam|trata)\b/;
const DEFINE = /^(o que (e|sao|significa|significam|quer dizer)|qual (e )?(o|a) (definicao|conceito|significado)|defina|definicao de|conceito de|significado de)\b/;
const LER = /\b(o que (diz|dispoe|estabelece|preve|determina|fala)|leia|ler|mostre|mostrar|mostra|texto|transcrev|teor|conteudo|na integra|redacao atual)\b/;

let tipo = 'tema';
if (v.troca || (alvos.length && ALTERA.test(qn))) tipo = 'alteracao';
else if (DEFINE.test(qn)) tipo = 'definicao';
else if (alvos.length && LER.test(qn) && !ANALISE.test(qn)) tipo = 'artigo';
else if (LOCALIZA.test(qn) && !ANALISE.test(qn) && !ALTERA.test(qn)) tipo = 'localizar';

let saida = null;

// ---- localizar: lista exata por programa ----
if (tipo === 'localizar') {
  let termos = aspas.slice(), extraido = false;
  if (!termos.length) {
    const m = q.match(/(?:falam|fala|tratam|trata|mencionam|menciona|citam|cita|cont[eê]m|t[eê]m|possuem|possui|aparece[m]?|o termo|a palavra|a express[aã]o)\s+(?:de|do|da|dos|das|sobre|o|a|os|as|em)?\s*([^?!.;]{2,60})/i);
    if (m) { termos = [m[1].replace(/\s+(na|da|nesta|desta)\s+minuta.*$/i, '').replace(/^(o|a|os|as)\s+/i, '').trim()]; extraido = true; }
  }
  termos = termos.filter((t) => t.length >= 2).slice(0, 4);
  if (!termos.length) tipo = 'tema';
  else {
    const res = termos.map((t) => ({ termo: t, achados: achar(t) }));
    const total = res.reduce((s, r) => s + r.achados.length, 0);
    if (!total && extraido) tipo = 'tema';      // termo deduzido sem aspas e nada achado: deixa a IA interpretar
    else {
      const linhas = res.map((r) => {
        const oc = r.achados.reduce((s, x) => s + x.ocorrencias, 0);
        if (!r.achados.length) {
          // expressão não encontrada: mostra onde aparecem as palavras dela, para orientar uma nova busca
          const PARE = new Set(['para', 'como', 'sobre', 'entre', 'pelos', 'pelas', 'desta', 'deste', 'minuta']);
          const palavras = semAc(r.termo).split(/\s+/).filter((w) => w.length >= 4 && !PARE.has(w));
          const perto = palavras.length > 1 ? palavras.map((w) => { const a = achar(w.replace(/s$/, ''), true); return a.length ? '“' + w + '…” em ' + a.slice(0, 8).map((x) => rot(x.artigo)).join(', ') + (a.length > 8 ? ' e mais ' + (a.length - 8) : '') : null; }).filter(Boolean) : [];
          return '“' + r.termo + '” não aparece em nenhum dos ' + arts.length + ' artigos.' + (perto.length ? ' Palavras parecidas: ' + perto.join('; ') + '.' : '');
        }
        const tit = {}; r.achados.forEach((x) => { tit[x.titulo] = (tit[x.titulo] || 0) + 1; });
        return '“' + r.termo + '” aparece ' + oc + ' vez' + (oc > 1 ? 'es' : '') + ' em ' + r.achados.length + ' artigo' + (r.achados.length > 1 ? 's' : '') +
          '. Por título: ' + Object.entries(tit).map(([t, n]) => (t || 'sem título') .split(' – ')[0] + ' (' + n + ')').join('; ') + '.';
      });
      const todos = [...new Set(res.flatMap((r) => r.achados.map((x) => x.artigo)))].sort((a, b) => a - b);
      saida = {
        resposta: linhas.join('\n') + '\n\nContagem feita por programa nos ' + arts.length + ' artigos (ignora acentos e maiúsculas; palavra inteira).' +
          (extraido ? ' Termo entendido: “' + termos[0] + '”. Para buscar outro termo exato, coloque-o entre aspas.' : ''),
        fontes: todos.map((n) => ({ artigo: n })),
        lista: res.flatMap((r) => r.achados.map((x) => ({ termo: r.termo, artigo: x.artigo, ocorrencias: x.ocorrencias, trecho: x.trecho }))),
        impactos: [],
      };
    }
  }
}

// ---- ler artigo: texto integral ----
if (tipo === 'artigo') {
  const ns = alvos.filter((n) => porNum.has(n)).slice(0, 5);
  saida = {
    resposta: ns.map((n) => { const a = porNum.get(n); return (a.breadcrumb ? '[' + a.breadcrumb + ']\n' : '') + a.texto_artigo; }).join('\n\n'),
    fontes: ns.map((n) => ({ artigo: n })), impactos: [],
  };
}

// ---- definição: glossário (+ onde o termo aparece) ----
if (tipo === 'definicao') {
  let alvo = aspas[0] || qn.replace(DEFINE, '').replace(/^\s*(o termo|a palavra|a expressao|o|a|os|as)\s+/, '').replace(/\s+(na|da|nesta|desta|segundo a)\s+minuta.*$/, '').replace(/[?"']/g, '').trim();
  const g = alvo.length >= 3 && (gloss.find((x) => semAc(x.termo) === semAc(alvo)) || gloss.find((x) => semAc(x.termo).replace(/\s*\(.*\)$/, '') === semAc(alvo))
    || gloss.find((x) => semAc(x.termo).includes(semAc(alvo)) || semAc(x.termo).includes('(' + semAc(alvo) + ')')));
  if (!g) tipo = 'tema';
  else {
    const base = String(g.termo).replace(/\s*\(.*?\)\s*$/, '');
    const ach = achar(base);
    saida = {
      resposta: g.termo + ': ' + g.definicao + '\n\n(Definição do glossário da minuta.)' +
        (ach.length ? '\n\nO termo aparece em ' + ach.length + ' artigo' + (ach.length > 1 ? 's' : '') + ': ' + ach.slice(0, 40).map((x) => rot(x.artigo)).join(', ') + (ach.length > 40 ? '…' : '') + '.' : ''),
      fontes: ach.slice(0, 40).map((x) => ({ artigo: x.artigo })), impactos: [],
    };
  }
}

const precisa_ia = !saida;
const out = { ...v, tipo, precisa_ia };
if (saida) {
  saida = Object.assign(saida, { pergunta: q, tipo, rota: 'programa', custo_usd: 0,
    aviso_rota: 'Respondido por programa, sem IA (custo zero).',
    varredura: { total_artigos_percorridos: arts.length, termos: [], checklist: [], nao_avaliados_pela_ia: [] } });
  out.saida = saida;
  out.registro = { pergunta: q, pergunta_norm: cfg.pergunta_norm, versao: cfg.versao, tipo, rota: 'programa', resposta: saida,
    valida: true, custo_usd: 0, duracao_ms: Date.now() - cfg.t0 };
}
// textos grandes não precisam seguir adiante quando a resposta já está pronta
if (saida) { delete out.minuta_texto; delete out.glossario_texto; }
return [{ json: out }];

const cfg = $('Configurar e Validar').first().json;
const v = $input.first().json;

const instrucoes = [
  'Você apoia a Comissão da Câmara Municipal de Curitiba na análise do Projeto de Lei de revisão do Plano Diretor.',
  (v.modo === 'completo'
    ? 'Você recebe a MINUTA COMPLETA e o GLOSSÁRIO. Responda em português, com base SOMENTE nesse texto.'
    : 'Você recebe os ARTIGOS DA MINUTA selecionados por uma varredura literal de todos os 355 artigos, e os termos de glossário citados. Responda em português, com base SOMENTE nesse texto; se precisar de um artigo que não veio, diga qual.'),
  'Cite sempre o artigo (e inciso/parágrafo) no formato "Art. 45, § 2º, III".',
  'Não emita opinião sobre o mérito político das propostas; descreva efeitos jurídicos e de redação.',
  'Quando a pergunta for sobre ALTERAR um texto (ex.: trocar "poderá" por "deverá"), explique: o que muda no próprio artigo',
  '(faculdade vira obrigação, quem passa a ser obrigado, se surge prazo ou necessidade de regulamentação/orçamento),',
  'e quais outros artigos são afetados: os que remetem a ele, os que tratam do mesmo instrumento/conceito,',
  'os que ficariam contraditórios ou redundantes, e os que dependem dele.',
  'Você recebe também uma VARREDURA feita por programa em todos os artigos. Avalie TODOS os artigos da lista "checklist",',
  'sem pular nenhum, e acrescente outros que você identificar lendo a minuta (marque origem "leitura").',
  'Se a varredura indicar que um termo da alteração não aparece no artigo citado, avise o usuário antes de analisar.',
  'Se nada for afetado, diga isso explicitamente.',
  'Quando a troca for na minuta inteira, a resposta deve dizer quantos artigos e ocorrências mudam e agrupar os efeitos por tipo',
  '(ex.: competências do Executivo que viram obrigação, faculdades de particulares que viram dever, exceções que viram regra),',
  'destacando os de maior impacto. Atenção a construções como "não poderá", que viraria "não deverá" e mudaria o sentido.',
  'Seja conciso: "motivo" com no máximo 15 palavras. Comece o JSON pelo campo "resposta".',
  'Responda APENAS com um JSON válido, sem texto antes ou depois, neste formato:',
  '{"resposta": "texto corrido, objetivo", "impactos": [{"artigo": 45, "nivel": "direto|indireto|sem impacto", "origem": "varredura|leitura", "motivo": "uma frase"}], "artigos": [45, 46]}',
].join('\n');

const varredura = {
  artigos_citados: v.alvos,
  pergunta_de_alteracao: v.eh_alteracao,
  troca_proposta: v.troca,
  termos_entre_aspas: v.termos.map((t) => ({ termo: t.termo, papel: { tema: 'tema buscado', original: 'termo que seria substituído', novo: 'termo novo (só contado)', edicao: 'texto da alteração proposta' }[t.papel],
    ocorrencias_no_artigo_citado: t.no_alvo, total_na_minuta: t.total, artigos: t.artigos.map((x) => x.artigo) })),
  remissoes_aos_artigos_citados: v.remissoes,
  mesma_secao: v.mesma_secao,
  conceitos_compartilhados: v.conceitos,
  checklist: v.checklist,
};

const body = {
  model: cfg.modelo,
  max_tokens: cfg.max_tokens,
  system: [
    { type: 'text', text: instrucoes },
    // Bloco grande e estável: fica em cache por 1 hora; as perguntas seguintes leem a minuta do cache.
    // No modo completo o bloco é igual em toda pergunta e fica em cache; no econômico ele muda a cada pergunta,
    // então cache só encareceria (a gravação custa mais que a leitura normal).
    Object.assign({ type: 'text', text: (v.modo === 'completo' ? 'MINUTA COMPLETA (' + v.total_artigos_minuta + ' artigos)' : 'ARTIGOS SELECIONADOS (' + v.artigos_no_contexto + ' de ' + v.total_artigos_minuta + ')') + ':\n\n' + v.minuta_texto + '\n\nGLOSSÁRIO:\n' + (v.glossario_texto || '(nenhum termo citado)') },
      v.modo === 'completo' ? { cache_control: { type: 'ephemeral', ttl: '1h' } } : {}),
  ],
  messages: [{ role: 'user', content:
    'PERGUNTA:\n' + v.pergunta + '\n\nVARREDURA AUTOMÁTICA (todos os artigos foram percorridos):\n' + JSON.stringify(varredura) },
  ],
};
return [{ json: { body } }];

// Reaproveita o pedido montado no formato da Anthropic e converte para o Chat Completions da OpenAI.
const b = $input.first().json.body;
const sistema = (b.system || []).map((x) => x.text).join('\n\n');
return [{ json: { body: {
  model: b.model,
  max_completion_tokens: b.max_tokens,
  response_format: { type: 'json_object' },
  messages: [{ role: 'system', content: sistema }, ...b.messages],
} } }];

// Converte a resposta da OpenAI para o formato que "Formatar Resposta" já entende.
const r = $input.first().json;
const ch = (r.choices || [])[0] || {};
const u = r.usage || {};
const cache = (u.prompt_tokens_details || {}).cached_tokens || 0;
const fim = ch.finish_reason;
return [{ json: {
  content: [{ type: 'text', text: (ch.message || {}).content || '' }],
  stop_reason: fim === 'length' ? 'max_tokens' : (fim === 'stop' ? 'end_turn' : (fim || null)),
  model: r.model || null,
  usage: { input_tokens: (u.prompt_tokens || 0) - cache, cache_read_input_tokens: cache, output_tokens: u.completion_tokens || 0 },
} }];

const v = $('Varredura Completa').first().json;
const r = $input.first().json;
const bruto = (r.content || []).filter((c) => c.type === 'text').map((c) => c.text).join('');
const parada = r.stop_reason || null;
let saida;
try {
  const ini = bruto.indexOf('{'), fim = bruto.lastIndexOf('}');
  saida = JSON.parse(bruto.slice(ini, fim + 1));
} catch (e) {
  // JSON cortado (limite de tamanho): recupera o que der da resposta e dos impactos já escritos
  const res = bruto.match(/"resposta"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  let texto = '';
  try { texto = res ? JSON.parse('"' + res[1] + '"') : ''; } catch (e2) { texto = res ? res[1] : ''; }
  const imp = [...bruto.matchAll(/\{\s*"artigo"\s*:\s*(\d+)\s*,\s*"nivel"\s*:\s*"([^"]+)"\s*,\s*"origem"\s*:\s*"([^"]+)"\s*,\s*"motivo"\s*:\s*"((?:[^"\\]|\\.)*)"\s*\}/g)]
    .map((m) => ({ artigo: Number(m[1]), nivel: m[2], origem: m[3], motivo: m[4] }));
  saida = { resposta: texto || (imp.length ? '' : bruto), impactos: imp, artigos: [] };
}
let aviso = '';
if (parada === 'max_tokens') aviso = 'A resposta da IA passou do limite de tamanho e foi cortada; o que veio está abaixo. Para perguntas muito amplas, aumente MAX_TOKENS_RESPOSTA ou divida a pergunta.';
else if (!bruto.trim()) aviso = 'A IA não devolveu texto (motivo de parada: ' + (parada || 'desconhecido') + ').';

const existe = new Set(v.checklist.map((c) => c.artigo));
const total = v.total_artigos_minuta;
const valido = (n) => Number.isInteger(n) && n >= 1 && n <= total;
// um artigo por linha: se a IA repetiu, fica a avaliação mais grave
const peso = { 'direto': 0, 'indireto': 1, 'sem impacto': 2 };
const porArt = new Map();
for (const i of (saida.impactos || []).map((i) => ({ ...i, artigo: Number(i.artigo) })).filter((i) => valido(i.artigo))) {
  const ant = porArt.get(i.artigo);
  if (!ant || (peso[i.nivel] ?? 3) < (peso[ant.nivel] ?? 3)) porArt.set(i.artigo, i);
}
const impactos = [...porArt.values()];
const avaliados = new Set(impactos.map((i) => i.artigo));
const naoAvaliados = [...existe].filter((n) => !avaliados.has(n));
let usados = [...new Set([...(saida.artigos || []).map(Number), ...impactos.filter((i) => i.nivel !== 'sem impacto').map((i) => i.artigo)])].filter(valido).sort((a, b) => a - b);

return [{ json: {
  pergunta: v.pergunta,
  resposta: [aviso, String(saida.resposta || '').trim()].filter(Boolean).join('\n\n') || 'Não consegui formular uma resposta.',
  parada,
  impactos: impactos.sort((a, b) => a.artigo - b.artigo),
  fontes: usados.map((n) => ({ artigo: n })),
  varredura: {
    total_artigos_percorridos: total,
    artigos_citados: v.alvos,
    termos: v.termos.map((t) => ({ termo: t.termo, papel: t.papel, total: t.total, artigos: t.artigos.map((x) => x.artigo), no_alvo: t.no_alvo })),
    checklist: v.checklist,
    nao_avaliados_pela_ia: naoAvaliados,
    modo: v.modo,
    artigos_enviados_a_ia: v.artigos_no_contexto,
    artigos_fora_por_limite: v.artigos_fora_por_limite || [],
  },
  uso: r.usage || null,
  modelo: r.model || null,
} }];

const cfg = $('Configurar e Validar').first().json;
const cl = $('Classificar e Responder').first().json;
const s = $input.first().json;
// preço por milhão de tokens (Anthropic). Haiku 5.5 muda de faixa acima de 100 mil tokens de entrada.
const u = s.uso || {};
const ent = u.input_tokens || 0, grava = u.cache_creation_input_tokens || 0, le = u.cache_read_input_tokens || 0, sai = u.output_tokens || 0;
const total = ent + grava + le;
let p = total > 100000 ? { i: 0.5, w: 1, r: 0.05, o: 2.5 } : { i: 0.10, w: 0.20, r: 0.01, o: 0.50 };
if (/sonnet/.test(s.modelo || '')) p = { i: 2, w: 4, r: 0.10, o: 10 };
if (/luna/.test(s.modelo || '')) p = { i: 0.10, w: 0, r: 0.01, o: 0.50 };       // OpenAI gpt-6-luna (padrão)
else if (/sol/.test(s.modelo || '')) p = { i: 2, w: 0, r: 0.10, o: 10 };       // OpenAI gpt-6.1-sol
const custo = Math.round(((ent * p.i + grava * p.w + le * p.r + sai * p.o) / 1e6) * 1e6) / 1e6;
const valida = !s.parada || s.parada === 'end_turn';
const saida = Object.assign({}, s, { tipo: cl.tipo, rota: 'ia', custo_usd: custo,
  aviso_rota: 'Analisado por IA (' + (s.modelo || 'modelo') + ') a partir da varredura dos ' + (s.varredura ? s.varredura.total_artigos_percorridos : '') + ' artigos.' });
return [{ json: { saida, registro: {
  pergunta: cfg.pergunta, pergunta_norm: cfg.pergunta_norm, versao: cfg.versao, tipo: cl.tipo, rota: 'ia', resposta: saida, valida,
  modelo: s.modelo, tokens_entrada: total, tokens_saida: sai, custo_usd: custo, duracao_ms: Date.now() - cfg.t0,
} } }];
